quests[47755] = { id = 47755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captured and Enraptured", description = "You gotta help me! Me and my crew were running late on a delivery, so we decided to take a detour through this grotto ahead. Boy... that was a mistake. This place is crawling with sirens!\n\nIf there's one thing my men like more than women, it's grog! Here, take some. Use it to bring them back to their senses. Might be best to rough 'em up a bit to weaken the enchantment.", progress = "Were you able to free my men? Without them, I'm stranded!", completion = "My men have been reporting back to me. Thanks for freeing them, {name}.", objectives = "Free 6 Enthralled Sailors in Fogcliff Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47756] = { id = 47756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Libation's Liberation" }
quests[47767] = { id = 47767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Metal Knight" }
quests[47771] = { id = 47771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locating the Longshot", description = "We're going to need a bigger gun if we hope to free Xe'ra.\n\nOne of the other bunkers crashed closer to the Xenedar. If Baraat was on it, he will have already begun surveying the area. Perhaps he's found the main cannon of the ship.\n\nIf you head over that way, make sure he hasn't died, will you?", completion = "We're under too much pressure here. And it's so close to us...", objectives = "Find Baraat the Longshot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47772] = { id = 47772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sky Ablaze With Cannonfire", description = "Oh! It's me! And {name}, was it? I remember this!\n\nI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.\n\nThink you could take it out for me?", progress = "Any luck? I just need the Horde cannon taken disabled if I want to escape.", completion = "You did it! Now hurry along... if I remember this correctly, you don't have much time left!", objectives = "Destroy the Horde Siege Cannon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47773] = { id = 47773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sky Ablaze With Cannonfire", description = "Oh! It's me! And {name}, was it? I remember this!\n\nI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.\n\nThink you could take it out for me?", progress = "Any luck? I just need the Alliance cannon taken disabled if I want to escape.", completion = "You did it! Now hurry along... if I remember this correctly, you don't have much time left!", objectives = "Destroy the Alliance Siege Cannon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47790] = { id = 47790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsettled Power", description = "The release of the energy previously trapped in the Nightwell has... complicated the influence of Aman'Thul scattered about the Broken Isles. Sadly, the results of my previous work have been invalidated, much like the contents of this vial.\n\nI must understand what has caused this change! Please, bring me more samples so that I may continue my work. It goes without saying that you will be the beneficiary of any breakthroughs I may find.", progress = "The people of Suramar spent 10,000 years tapping into the latent energies of a dead titan. I wonder if any of them considered what might happen if they suddenly stopped doing so.", completion = "I've managed to stabilize the mixture without diminishing its potency. No simple task, mind you, and I do hope you will appreciate the hard work it took to get this far.\n\nI feel a great sense of unease regarding what might have been the source of this disruption. One would have expected that releasing Aman'thul's power would bring harmony, not chaos.", objectives = "Bring 50 Writhing Essence to Arcanomancer Vridiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47791] = { id = 47791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsettled Power", description = "It is deeply disconcerting that the power of Aman'thul grows increasingly unstable. We must pursue this matter further.\n\nIs this volatility the result of the Legion's corruption? No, that is too recent an influence. Something else must have...\n\n<Vridiel trails off absentmindedly, not looking directly at you.>", progress = "I must discover the source of the unrest present in these samples.", completion = "Maddening! I am no closer to a breakthrough on this matter. Such a failure is unacceptable!\n\n<Vridiel breathes deeply and composes himself.>\n\nThank you, {name}. I must not let this setback deter me from further attempts. Please, take this. You will no doubt find a use for it.", objectives = "Bring 50 Writhing Essence to Arcanomancer Vridiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47793] = { id = 47793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spoiled Sample", description = "<You pick up a vial of thick, inky liquid. Its contents react to your touch, boiling and popping furiously for a moment before settling down into a persistent glow. The substance resembles arcwine in this form, but the reaction reminds you of the breakdown of obliterum.\n\nYou tuck the vial in your bags. Someone in Dalaran familiar with the obliterum forge might know more.>", completion = "This is worrisome. Gul'dan's defeat may have disrupted forces far more fundamental than anyone realized. \n\nHmm... perhaps we can turn that to our advantage.", objectives = "Bring the Spoiled Sample to Arcanomancer Vridiel in Dalaran on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
