quests[47806] = { id = 47806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Assistant" }
quests[47807] = { id = 47807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worried About My Friends", description = "I've heard about some trouble over at the black dragonshrine. I know, I'm a bronze dragon, but still! I worry about them sometimes! They weren't ALWAYS so grumpy.\n\nIf you're going there anyways, would you mind taking care of... whatever's causing so much of a disturbance?", progress = "I don't know what I'd do without my aspect. Must be tough.", completion = "It was a dreadlord? That's... unusual. I mean, I know we're in Northrend and everything, so risen skeletons aren't all that rare, but demons?\n\nOh well! Thanks for taking the time to calm my worries.", objectives = "Slay Zorathides at the Obsidian Dragonshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47808] = { id = 47808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Walk", description = "Greetings, {race}. I know you are here in the service of the bronze, but I have a request of you.\n\nThe Ruby Dragonshrine is plagued by undead. My shrine's wardens were unprepared, and we risk losses if an intervention is not done quickly. Would you assist us?", progress = "Thank you for hearing my request.", completion = "You have my thanks, {race}.\n\nI know that you are here today in service to the Bronze Dragonflight. Perhaps this gift will aid you in your journeys.", objectives = "Slay Talar Icechill at the Ruby Dragonshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47809] = { id = 47809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness in the Ley", description = "A strange, dark disturbance perturbs the ley lines in my flight's dragonshrine. Do you have the time to investigate?", progress = "<Kalecgos eyes you cautiously.>", completion = "Your assistance is appreciated.", objectives = "Slay the Void Gargantuan at the Azure Dragonshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47810] = { id = 47810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkened Dreams", description = "The ancients at the Emerald Dragonshrine suffer in their dreams. With Ysera gone, I am shorthanded and unable to investigate the matter myself. Would you help me cleanse the nightmare from the Emerald Dragonshrine?", progress = "I appreciate you taking the time to listen to my concern, {race}.", completion = "With your assistance, the ancients have fallen back into their restful slumber. Thank you, {race}.", objectives = "Slay Thalas Vylethorn at the Emerald Dragonshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
