quests[47835] = { id = 47835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Fate", completion = "I knew you would be among those called to fight. It will be an honor to fight by your side.", objectives = "Meet your escort to the Exodar at Bladefist Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
