quests[47850] = { id = 47850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47851] = { id = 47851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Marks of Honor", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
quests[47852] = { id = 47852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47853] = { id = 47853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flanking Maneuvers", description = "I will take command of Fareeya's lieutenants and we will escort Velen to the Crest of Knowledge. His mission must not fail.\n\nWe face an old foe-- one the Army of the Light has encountered on numerous occasions. Talgath will try to block us in and prevent our retreat.\n\nYou must not let that happen. Find out how he is bringing in his forces and cut them off. All we need is time to get in and get out.\n\nWe are counting on you.", completion = "<Velen stares at the shattered statue before him and says nothing.>", objectives = "Close 3 Legion Portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47854] = { id = 47854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the High Exarch", description = "Where the Legion is concerned, violence is always the answer.\n\n<Turalyon hefts his blade with a grim expression.>\n\nThey are between us and Velen. Nothing will stop them from finding him unless we act. Now is not the time to hold back.\n\nTogether we will sow chaos among their ranks.", completion = "If I have learned anything about the Legion, it is that we have no other option but to fight back.\n\nIt was a pleasure to have you at my side.", objectives = "Disrupt the Legion forces in Arinor Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47855] = { id = 47855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Might Have Been", description = "<Velen continues to stare at the statue as he speaks.>\n\nThousands of years ago, when I was young, I made a choice.\n\nA choice that allowed my world to fall to ruin. A choice that made my people exiles. A choice that forever separated me from my beloved brothers.\n\n<Velen shakes his head.>\n\nI cannot leave, not yet. Not until I have had a chance to reflect.", progress = "Memory roots me in place, more surely than the heaviest stone.", completion = "<Prophet Velen peers solemnly at you.>\n\nThank you.", objectives = "Witness Velen's memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47856] = { id = 47856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across the Universe", description = "Talgath. There was a time I called him an ally, a friend.\n\nI put my trust in him when it came time to leave Argus. I asked him to call out to the others who would join me.\n\nI gave him all that he needed to betray me and slaughter my followers.\n\nI do not know what brought this hatred to lurk in his heart, but his machinations repeatedly forced my people to flee world after world. He made it his mission to hunt us across the universe.\n\nThis must end, {name}. Talgath must die.", completion = "It is done. This one wrong, of many, is finally set to rights.", objectives = "Defeat Talgath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47857] = { id = 47857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Hey you've finished part 1 of the Velen arc. Stop here. Nothing past this point is done.", sourceObjective = "Stop here. Do not pass go. Do not collect 200 dollars.", sourceObjectiveStatus = "unverified-source-field" }
quests[47858] = { id = 47858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Security: Engaged" }
quests[47859] = { id = 47859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47863] = { id = 47863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47864] = { id = 47864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Additional Marks of Honor", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
quests[47865] = { id = 47865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Piles of Marks of Honor", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
quests[47866] = { id = 47866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47867] = { id = 47867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two If By Sea", description = "The draenei have crafted a vessel to take us to Argus safely. They are gathering the invasion force on Azuremyst Isle as we speak. \n\nWe will join them there by sea. The Legion is no doubt keeping a close eye on the gateway to their world. We must retain the element of surprise.\n\nLet me know when you are ready.", completion = "May the Light protect us all this day.", objectives = "Speak to Lady Liadrin to set sail for the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47868] = { id = 47868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Necropolis", description = "A deal is a deal, and I pay my debts.\n\nBwonsamdi is a mighty loa and you are going to need a powerful ritual to obtain his attention.\n\nYou are in luck. I already know exactly what needs to be done.\n\nBwonsamdi's temple, de Necropolis, is just to de north. Meet me in de courtyard and we shall see about obtaining an audience with de loa of death.", completion = "Ah, there you are. We are ready to start.", objectives = "Speak with Hanzabu in the courtyard of the Necropolis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47870] = { id = 47870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Men Tell No Tales", description = "I'm an employee of the Ashvane Company. We're number one in the Azerite trade. \n\nWhen I took this job, no one told me it would be a one-way trip!\n\nI'd do just about anything to escape these dunes, including working with you.\n\nMaybe we can help each other out?\n\nI'd be willing to part with the code to the captain's lockbox, if you're willing to help me escape this wretched desert.\n\nFor my plan to succeed, my expedition party needs to die. Can't have them telling anyone I'm missing...", completion = "So it's done then? I never really liked Hendricks, anyway.", objectives = "Kill the remaining members of Randall's expedition party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47871] = { id = 47871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seafaring Necessities", description = "She might not be much to look at, but this boat will take me back to Boralus. \n\nBefore my voyage can begin, I'll need a few seafaring necessities. \n\nLuckily, everything I need can be found in the Ashvane encampment.", progress = "Have you had any luck securing those items I asked for?", completion = "This should all help me get to where I need to go.", objectives = "Collect a Seafaring Hat, Nautical Map, and Weathered Spyglass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47873] = { id = 47873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Cache", description = "Well, I'm sure you've figured it out by now, eh?\n\nI never was fixing to abandon the crew, I just wanted to move up the ranks. You've helped me out a great deal in that respect.\n\nSpeaking of respect, I believe there's the matter of Captain Hartford's lockbox...\n\nHere's the code, courtesy of the fallen captain. Just as I promised. It's all yours!\n\nNow, don't go telling anyone about our little arrangement, okay? I wouldn't want something like that to spoil such a profitable partnership!", completion = "<The chest creaks open.>", objectives = "Loot Captain Hartford's cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47874] = { id = 47874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Fog", description = "Did you lead Kaja here? I told her not to come after me. It isn't safe...\n\nMy mind remains fogged, but de memories are slowly returning. Jakra'zet... de weapon...\n\nCome, let us find some fresh air. I will tell you what I've discovered.", completion = "Talanji was right not to trust de general. If he succeeds in finding de weapon, our great city will fall.", objectives = "Follow Warguard Rakera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47880] = { id = 47880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tribute for Death", description = "Everything for de ritual is together. Now, it is time to begin. \n\nFor dis to work, I must chant de words of old. It is an exhausting task, so I need you to take my mojo fetish and draw de ritual circle, then beat upon de drums.\n\nIf all goes well, Bwonsamdi may invite us into de temple.\n\nIf not, our souls are forfeit.\n\nLet's not make any mistakes.", completion = "Ya be brave ta come here, but ya need ta have more than just bravery if ya be wantin' Bwonsamdi's favor.", objectives = "With Hanzabu's Ritual Fetish, draw the ritual circle and sound the Drum of the Spirits to complete the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47881] = { id = 47881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47882] = { id = 47882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conservation of Magic", description = "I have an idea. This construct will be of use to us. We simply need to jolt it awake.\n\nWe once stored great quantities of energy in conduits throughout the Conservatory. They are still functional, but only just.\n\nTake this.\n\n<Y'mera hands you a brightly glowing crystal.>\n\nIt will provide a small burst of magic that should help stabilize an erratic conduit. I think I have enough stored for eight or so.\n\nStabilizing a few should allow us to access the whole network.", completion = "Yes, excellent. The conduits are back online.\n\nThe construct however is proving a little more difficult to awaken than I had hoped.", objectives = "Stabilize 8 Erratic Power Conduits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47883] = { id = 47883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Longest Vigil", description = "It was a good thing we sought two sources of energy. Even with the conduits active, the construct has not stirred.\n\nIt has likely been inactive a long while. Perhaps as long as Eredath has floated above Argus.\n\nWhat a long, lonely vigil it must have been.\n\n<Y'mera is silent for a moment as she peers at the construct.>\n\nGo ahead and jostle it a little. That combined with one last burst of magic ought to do the trick.", completion = "Prepare yourself, stranger.", objectives = "Wake the Gatekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47885] = { id = 47885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47889] = { id = 47889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker Calls", description = "Magni sent for you to meet him in the Krokul Hovel. He has found something that he believes could help us overcome the Legion's infinite armies.\n\nWe need every advantage we can muster if we are to see this war through. You should seek him out.", completion = "Thank ye fer joinin' me, lad. There's somethin' ye have to see.", objectives = "Meet Magni in the Krokul Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47890] = { id = 47890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of Torment", description = "I've been hearin' whispers ever since we got to Argus. They're just like Azeroth's, only... they ain't hers.\n\nI'm convinced that Argus has a titan of its own that's reachin' out to us!\n\nThe broken have a relic stowed away that's darn near holy to 'em. Hatuun says they hear whispers from it... I think it might have some sort o' link to Argus itself!\n\nIt's just in this chamber. Let's see what we can learn.", progress = "I know, I know, it's a lot to ask, but we need all the help we can get lad!", completion = "I don't know how Sargeras managed to raise Aggramar, but it's bad news for us, believe you me.", objectives = "Activate the Sacred Stone to witness Argus' vision with Magni.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47891] = { id = 47891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dire News", description = "Azeroth was right in sendin' us here, {name}. We have to stop whatever it is Sargeras is plannin', or we may not have a home left to save when this is all over.\n\nYe should go back to Turalyon and let him know what ye've seen. I'll stay here and see if I can't glean anything else that might help us.", completion = "What did Magni have to show you?", objectives = "Return to Turalyon on the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47892] = { id = 47892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Citadel", description = "We have already secured ground near Nath'raxas Hold. It is one of the Legion's chief military fortifications on Argus.\n\nStriking it now, and hard, may be our only opportunity to tip the scales in our favor.", completion = "If we do not act quickly, the demons stationed here are more than enough to overwhelm us.", objectives = "Travel to Destiny Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47894] = { id = 47894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jump Around" }
quests[47895] = { id = 47895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bert's Bots", description = "If I'm going to clean up Gnomeregan, I've got to be ready to battle all manner of rat, roach, and potentially even the dreaded mutant rat-roach.\n\nWhat I'm saying is that I need to put these bots to the test! A real, live-action field demo.\n\nAre your pets up for a code review?", progress = "Better bots, by Bert!", completion = "I'm going to have to go back to the drawing board!", objectives = "Defeat Bert in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47897] = { id = 47897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanchuli Traitors", description = "Dey are trying to cast down our loa, claiming dem to be false gods.\n\nDey have turned to de old ways of blood, sacrifice, and subjugation.\n\nI cannot even begin to say how offensive dis is. Kill any of dese traitors you find.", completion = "You killed how many? Well, dat is a start.", objectives = "Kill 10 Zanchuli traitors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47904] = { id = 47904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserve the True Future", description = "I know how this looks, {name}. I'm not asking for your help simply because I don't want to get killed.\n\nI need your help because this isn't how I'm SUPPOSED to die. I will die - I've seen it! - but it happens much later than this. Besides, meddling with the timeways for personal reasons - well, it goes against pretty much everything my dragonflight stands for.\n\nLet's stop all four of the dragonshrine attacks. That should do the trick.", completion = "We've stopped all four attacks from the dragonshrines - but the timelines are still incorrect. I'm still being assassinated, elsewhere, at the same time.\n\nLooks like our work isn't done yet, {name}!", objectives = "Stop the attacks from the Obsidian, Ruby, Azure, and Emerald Dragonshrines in one attempt of the Deaths of Chromie scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47906] = { id = 47906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deaths of Chromie", description = "It looks like we're going to have to stop all eight attacks on me. In one fifteen-minute span.\n\nEven to me, that doesn't seem like a lot of time.\n\nStill, if anybody can do it, it's us. Are you ready, {name}?", completion = "We've done it! The timelines are exactly as they're supposed to be again. With me, alive.", objectives = "Stop all eight attacks on Chromie in one attempt in the Deaths of Chromie scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47915] = { id = 47915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing the Taken", description = "We are doing our best to contain de fighting in Zanchul and not let it spill out into de other terraces, but we can't hold for long.\n\nIf you are going to help, start by freeing Wardruid Loti. Dey are trying to break her on de platform above with a dark ritual.\n\nHer soul is bound to a fetish. You must find dat fetish if you are going to free her.", progress = "Find... de... fetish.", completion = "Free at last! Oh, de pain is coming for dem now.", objectives = "Recover the Fetish of Loti.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47918] = { id = 47918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Serve Krag'wa", description = "There are other forces who seek to disturb my frogs. The vile naga attack my shores and drain my frogs of their magic!\n\nThey seek to use my followers as a feast for their thirst for mana. It must be stopped!\n\nA powerful shadow hunter named Narez is currently fighting them. You must go aid her and stop the naga from feasting on my frogs!", completion = "{name}! Krag'wa himself sent ya? By da loa, I be blessed dis day ta have him recognize me. I need ya help.", objectives = "Meet Shadow Hunter Narez in the Upper Frogmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47919] = { id = 47919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Say No to Cannibalism", description = "Of course the Natha'vor trolls have Shoak! Why would it be easy?\n\nI'm sick and tired of running from these trolls. That's why you're going in to end this.\n\nThe Natha'vor trolls have three powerful troll witch doctors called \"corpse mongers\". Take them out and you'll send the tribe into disarray.\n\nOf course, this could all fail spectacularly and make my terrible day even worse.", completion = "Good work. The Natha'vor trolls should be in disarray now that those... things are out of the picture.", objectives = "Kill Corpse Mongers Jal'aka, Yon'gi, and Nog'shra", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47920] = { id = 47920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47921] = { id = 47921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47922] = { id = 47922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47923] = { id = 47923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47924] = { id = 47924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profanity Filter", description = "I hate this place! I just want to go home, but I can't because that oaf, Shoak, is missing.\n\nListen, {race}t, I'll make it worth your while if you help me find that dunce.\n\nI've got a way to find Shoak, but of COURSE these stupid totems are blocking my magic! Why wouldn't they?\n\nTake this scroll and use its magic to burn these totems. I'm going to look around to see if that bonehead is just sleeping somewhere.", progress = "You destroy those totems yet?", completion = "Looks like that dunce got himself captured by blood trolls.\n\nThis is going to get violent really fast.", objectives = "Destroy 5 Profane Totems with Kajosh's scroll of inferno.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47925] = { id = 47925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoak's on the Menu", description = "I don't know what stupid thing Shoak did to get captured by the Natha'vor trolls, we'll find out once you rescue him.\n\nI bet they're getting ready to make a meal out of Shoak. You need to work fast and get him out! \n\nShoak's one of the largest oafs that I know, those trolls won't be happy that you're taking their \"meal\" away.", completion = "Thanks again, I thought I was done for!", objectives = "Rescue Shoak from the Natha'vor trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47928] = { id = 47928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offering for the Loa", description = "The time has come for you to make contact with the great loa Eraka no Kimbul.\n\nI can only imagine what it will be like to be in the presence of such an ancient and powerful deity. You have earned the Ring of Tides, so it must be you that addresses the loa. \n\nPlease present the loa with this offering from our tribe. Tell him of our plight against the naga.\n\nEraka no Kimbul is our only hope of survival now.", progress = "You must meet with the loa. Are you ready?", completion = "It has been many years since I've had a visitor to my temple and been found worthy to wear the Ring of Tides.", objectives = "Meet with Eraka no Kimbul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47934] = { id = 47934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
