quests[47938] = { id = 47938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47939] = { id = 47939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If the Key Fits...", description = "These Ashvane are unreasonable. I've tried to bargain for my release, but they refuse any offer I bring to the table. \n\nAll they want is whatever's bubbling up in that mine. My kind know better than to go near that stuff. It's volatile.\n\nThere are prisoners in the mine being forced to extract it. Us in the cages? We're back up. When someone dies in the mines, they just send another in. \n\nIf you release me, I'll make sure you're rewarded! We just need to find the right key for this cage...", progress = "We need to find the right key to open this cage.", completion = "None of these keys work! We're going to have to find another way...", objectives = "Collect 6 Ashvane Trader Keys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47943] = { id = 47943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Trapping", description = "We are trapped here with little in the way of food and supplies.\n\nThe territorial sethrak control the land to the west, and the spiteful naga the waters to the east. We are caught between a barren desert and a hostile ocean.\n\nIf you are headed to the lagoon to face the naga, will you bring us back some crabs to eat?\n\nI fear that our tribe will soon perish without food...", progress = "Do you have a case of crabs?", completion = "You've arrived just in time, our supplies were getting dangerously low. The Tortaka tribe thanks you, traveler.", objectives = "Catch 8 Clampclaw Clackers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47945] = { id = 47945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Market, To Market", description = "Thanks heaps for getting us out of that pickle, mainlander. I'd hate to ask, but would you be willing to help with another matter?\n\nEven before this curse struck the village, our sausage shipments from Carver's Harbor started slowing down. If we don't get them sausages, I won't be able to feed my family!\n\nCan you help an honest sausage merchant out? Carver's Harbor is just down the road from here.", completion = "Thank the Light someone came!\n\nI can't handle this myself!", objectives = "Meet Thomas Staughton at Carver's Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47946] = { id = 47946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Their Bacon", description = "This is going to sound strange, {class}, but some of my workers were turned into pigs! Lucky I was out on an errand, or I'd have been caught too! Now my people are tied up awaiting... processing. \n\n<Thomas suppresses the urge to retch.>\n\nI can't get past those monsters, but you look like the sort who could. Not sure if this helps, but I coulda sworn I heard some wild cackling coming from the warehouse.\n\nPlease... save my people!", completion = "Thank you for sending my workers to a safe spot.\n\nHopefully my men won't have to remain pigs for long.", objectives = "Untie Trevor Hightide, Kyle Sailford, Travis Daybreak and Burke Stevenson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47947] = { id = 47947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Bad Wolves", description = "Wolves with strange, glowing eyes have taken over the area! I don't know what they are or why they're glowing but it cannot mean anything good. They have to be removed!\n\nPlease, {class}, slay them before more of my friends are killed.", completion = "With those monsters gone, no more of my people are going to get killed.", objectives = "Slay 10 Hexed Howlers in Carver's Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47948] = { id = 47948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pork Chop", description = "Roland Hacksaw was the best butcher I've ever worked with... but he's gone insane! He's still processing pigs into sausage!\n\nYou have to stop him!", completion = "Poor Roland. He was... very good at his work. One of the finest butchers in Drustvar. It is a true shame his talents were put to such horrible use.", objectives = "Slay Roland the Butcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47949] = { id = 47949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Not My Fetish", description = "<The glassy eyes of the pig fetish seem to follow you as you approach. The dark power emanating from the witch's fetish must be what is keeping the workers transformed. \n\nPerhaps Thomas Staughton might have some idea what to do with it.>", completion = "Removing it didn't break the curse? Damn. We'll have to try something else.", objectives = "Bring the Pig Fetish to Thomas Staughton.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47950] = { id = 47950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cured Ham", description = "That foul thing has to be what's keeping my men transformed into pigs.\n\nHmm. Well there isn't too much that can withstand a good cleansing fire! I say we burn it! \n\nToss it into the campfire!", progress = "Into the flames with that foul thing!", completion = "You did it! The spell is broken and my men are back to normal!\n\nWell... mostly. They're alive at least.\n\nNow we can get back to normal around here. If you see Elijah in Fallhaven, tell him he'll get his sausages soon.", objectives = "Toss the Pig Fetish into the campfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47952] = { id = 47952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Fleet", description = "The tidesage order has a sizable monastery right here in Boralus. I say we start our search for the fleet there.\n\nSomeone there has to know something, right? You don't just lose the entire legendary Kul Tiran fleet on accident!\n\nWe'll need to take a ferry over to the monastery. Make sure you bring your pass with you!", progress = "I've never been to the monastery before.", completion = "Keep your eyes open. I'm not sure we're entirely welcome.", objectives = "Charter a ferry to Stormsong Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47953] = { id = 47953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tereck the Selector" }
quests[47954] = { id = 47954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47956] = { id = 47956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47959] = { id = 47959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warguard's Trail", description = "Rakera's journal suggested she moved south. It's de only lead we have. \n\nMeerah is headed dat way, and has invited us to travel with her. \n\nThese vulpera know de desert better than any troll I've ever met. \n\nOur chances of survival are highest if we travel together.", completion = "Ah, you're looking for de warguard? She's de only reason I'm still breathing.", objectives = "Travel with Meerah's Caravan in search of Warguard Rakera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47960] = { id = 47960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiragarde Sound", description = "We must convince Katherine Proudmoore to pledge Kul Tiras to the Alliance. Flynn believes the Ashvane Trading Company's new gunpowder is our best lead.", completion = "Maybe with your help we can restore the people's faith in Proudmoore leadership.", objectives = "Offer to investigate the Ashvane Trading Company.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47961] = { id = 47961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustvar", description = "The stalwart protectors of House Waycrest hold fast along the western border, but recently all contact with them has been lost. We must secure their aid in order to bring Kul Tiras together under the Proudmoore banner.", completion = "I've only been to Drustvar once, on a hunting trip. It's a rugged land with a dark history and superstitious people. Steel yourself for this one.", objectives = "Offer to make contact with House Waycrest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47962] = { id = 47962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormsong Valley", description = "The Kul Tiran fleet has been lost at sea. The tidesages of Stormsong, with their mystical oceanic magic, may be our only way to locate the fleet of legend.", completion = "Even under normal circumstances, the tidesages would be wary of outsiders. I'll accompany you on this mission and maybe we can finally get some answers.", objectives = "Offer to investigate the missing Kul Tiran fleet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47963] = { id = 47963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient One", progress = "What kind of world we live in where da faithful must be da ones to rescue da gods?", completion = "Heretics and ingrates! All of them! I will drop every last one of them on a ROCK!\n\nGo, little {race}, and make sure the other loa are not falling into the same trap I did.", objectives = "Rescue Pa'ku.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47964] = { id = 47964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoe Shine Kit Tracking Quest" }
quests[47965] = { id = 47965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruined Temple", description = "The loa may be our only hope against the naga, but the temple lies abandoned and broken.\n\nTwo of my tribe have gone ahead to scout the ruins. They may be able to help you make contact with Eraka no Kimbul.\n\nIf the spirit of the loa remains at the temple, we must find a way for him to hear our plight.", completion = "I am afraid that we haven't had much success contacting the loa. The entrance to the temple is sealed and the rest of the ruins are overrun with jungle spiders.", objectives = "Speak with Teekcha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47967] = { id = 47967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Argus Roper", description = "My warriors stand no chance against even the smallest of the Legion's forces without our Cragscalers. If you can capture a few and bring them here, my warriors can better defend our people.", progress = "We need those talbuk!", completion = "With these new steeds our forces stand a chance.", objectives = "Return 3 Wild Cragscalers to Lead Rider Jerek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47968] = { id = 47968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs and Portents", description = "<The bulletin that Mayor White was posting at the time he was struck by the spell indicates that there have been some strange happenings in the town lately. \n\nIt is likely these events are connected to whatever cast this spell on the village.\n\nPerhaps there might be records from other villagers that could shed some light on the source of this magic.>", progress = "<The town's ledger lists a record of the comings and goings of people and goods through the city of Fallhaven.>", completion = "<The writings you were able to find all have one common thread - an old woman who recently arrived in town.\n\nThis ledger may contain some information to her whereabouts.>", objectives = "Investigate the villagers' writings in Fallhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47969] = { id = 47969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallhaven's Curse" }
quests[47978] = { id = 47978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Crone", description = "<The ledger indicates that an old woman named Helena Gentle recently took up residence in a house down the road from the town.\n\nThe villagers' writings point to her being involved somehow with a variety of maladies that struck the village recently. \n\nIt's possible that she may know what's behind this spell, if it hasn't afflicted her as well.>", completion = "Why hello there, young man.\n\nWe don't get many visitors to Fallhaven. What brings you to my home?", objectives = "Confront Helena Gentle in her home outside of Fallhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47979] = { id = 47979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witch Hunt", description = "A curse on the villagers? Oh my, how dreadful!\n\nAlthough, to be honest, there have been some strange happenings around Fallhaven of late. I wonder if these could be culprit?\n\nTake a seat and have a spot of tea. I'll tell you all that I know.", completion = "<The crone is defeated, and will no longer pose a threat to the people of Fallhaven.  \n\nHowever, her curse on the village still lingers...>", objectives = "Listen to Helena Gentle's story in the Shrouded Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47980] = { id = 47980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furious Familiars", description = "<The wildlife in the foothills appear to be under Helena's spell, and this villager appears to be one of their victims. \n\nThey must be the cause of the recent disappearances from Fallhaven.\n\nPerhaps if their numbers were cut down, they would pose less of a threat to the townspeople.>", objectives = "Kill 10 enthralled animals in the Shrouded Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47981] = { id = 47981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking the Curse", description = "<In her haste, it looks like Helena left her spellbook behind. The pages of this book detail the ritual that she used to entrap the villagers of Fallhaven. \n\nIt seems the effigy holding the spell in the village is protected by smaller ones surrounding the town. If these are destroyed, you may be able to affect the one holding the spell on the townsfolk.>", completion = "<The magical energies surrounding the effigy have dissipated.>", objectives = "Destroy the 4 Lesser Effigies in the Shrouded Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47982] = { id = 47982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Effigy", description = "<The effigy's protection has been broken.\n\nAll that remains is to break the effigy itself.>", completion = "What's... going on? How long have I been standing here?\n\nA curse!? You're saying the whole village was just... stuck? I knew there was something terribly wrong with that old crone...\n\nIt seems that Fallhaven owes you a great debt, stranger.", objectives = "Destroy the Cursed Effigy in Fallhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47986] = { id = 47986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scars of the Past", description = "The Army of the Light's warframes have won countless battles on Argus. Despite their power, not all who descend into the fray return.\n\nMy modifications to this frame should give us the edge we need, but several critical components are still missing.\n\nThere are remains of battles past in Nath'raxas that we can still scavenge. If you can find the pieces I need, the Legion will feel our fury yet.", progress = "Do you have the components?", completion = "Perfect! Thank you, {name}.", objectives = "Recover an Invocation Array, Vindicator Plating, and a Judgment Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47987] = { id = 47987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventive Measures", description = "There is no end to the Legion's depravity. Every battle won, every world conquered, yields more souls to fuel their war machine.\n\nThey have not yet defiled all of the fallen warriors in the hold, but I fear it is only a matter of time. Please, take this talisman with you into the hold and use it to sanctify any corpses you encounter.\n\nThey deserve a better fate.", completion = "Thank you, {name}. Your actions deny the Legion power and grant the dead the peace they deserve.", objectives = "Use the Talisman of the Prophet to sanctify 9 fallen Army of the Light warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47988] = { id = 47988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos Theory", description = "Despite their strength and their numbers, even the Burning Legion requires order to fight. Disrupt that order... and they fall like the rabble they are.\n\nThe plan is simple. Let chaos reign in their ranks, and the day will be ours.", progress = "We must do whatever it takes to see this done.", completion = "Now that their forces are in disarray, let us proceed.", objectives = "Kill 12 Nath'raxxan Fleshcarvers, Nath'raxxan Doomshots, or Ravenous Soulhunters, and 1 Nathrezim Banelord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47989] = { id = 47989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heralds of Apocalypse", description = "We've been presented with a rare opportunity.\n\nOur scouts have spotted two shivarra priestesses in the western fel pools enhancing the Legion's war effort.\n\nThe inner circle of Sargeras' chosen never leave the walls of Antorus. If we take them out, we might be able to sow fear among those closest to the Dark Titan.", completion = "Impressive. Without the shivarra bolstering their strength we just might stand a chance.", objectives = "Slay Lady Heretica and Mistress Apostriss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47990] = { id = 47990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Touch of Fel", description = "Our warframe is almost operational! It just needs a good jolt to revitalize its systems.\n\nWarlocks in the pools below infuse pieces of Argus with fel energy to create living siege weapons. If you can extract one, we can use it to jumpstart the warframe's Judgment Core!", progress = "Remember - immaculate!", completion = "Yes! This is it!", objectives = "Collect an Immaculate Felcore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47991] = { id = 47991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Machinations", description = "Eredar are adept at manipulating the fel that courses through this world. Those who do not shape it into living weapons build other armaments, like the Spires of Woe.\n\nThe spires will make it difficult for even a small force to penetrate the main stronghold. We must dismantle enough of them to clear the way before we advance upon it.", progress = "We do not have time for failure.", completion = "No war is won by a single act, but without the spires protecting them the rest of the hold will fall as well.", objectives = "Dismantle 3 Spires of Woe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47992] = { id = 47992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawn of Justice", description = "Thanks to your efforts, our enemy is in disarray and their defenses inoperable.\n\nWe must take the ground at the spire's base and tighten the noose around their commander's neck.\n\nYou have more than earned the honor to take the warframe into battle. We will follow your lead once the way is clear.", completion = "Well fought! Now for the commander.", objectives = "Use the Lightforged Warframe to take control of the Court of the Avenger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47993] = { id = 47993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord of the Spire", description = "Lord Nath'raxas rules over this hold as thanks for his role in delivering Argus to the Legion many years ago.\n\nMake no mistake, he is powerful, but he has also grown overconfident in his seat.\n\nTake advantage of his hubris and make use of the warframe's firepower while you can. We will storm the courtyard shortly!", completion = "By the Light...", objectives = "Defeat Lord Nath'raxas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47994] = { id = 47994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forming a Bond", objectives = "Now that it has been thoroughly tested, I will direct our artificers to energize the warframe once more so that you may call it into battle. If you wish, you may select it at the Matrix Core at your leisure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47995] = { id = 47995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overt Ops", description = "My soldiers are out there, {name}.\n\nI need you to find Baraat, Sorvos, and Telaamon. They were in the process of securing this area for Velen when the Legion came down on top of our heads.\n\nInform them that their orders are to regroup with the Prophet at once.\n\nThe time for subtlety has passed. There is a small army between us and them. Do what you must.\n\nLight keep you safe.", completion = "Fareeya's forces are the best the Army of the Light has to offer. Our mission is that much more likely to succeed with them at our side.", objectives = "Locate Baraat the Longshot, Grand Vindicator Sorvos, and Blademaster Telaamon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47996] = { id = 47996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawfiend Extermination" }
quests[47997] = { id = 47997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47998] = { id = 47998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing Cannibals", description = "Shoak and I have had a few run-ins with the Natha'vor trolls. Must be why they wanted to capture that idiot.\n\nThe women in that tribe actually eat the men... and anyone else they can get their hands on. I'm sure they're getting ready to eat Shoak.\n\nDo us all a favor and kill some of those cannibals. The world would be a better place without them.", progress = "Well? Did you take care of those cannibals?", completion = "I could hear their screams from here.\n\nThese blood trolls are monsters, {race}. Who eats their own people?", objectives = "Kill 10 Natha'vor Cannibals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47999] = { id = 47999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48000] = { id = 48000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48002] = { id = 48002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Limited Supplies", description = "Hello, {name}. It's good to see a fellow alchemist again.\n\nI've been supplying our camp with necessary potions to deal with the demons, but lately I've been running low on supplies. Normally when scouting parties go out, they return with empty vials, but as of late fewer have been returning.\n\nI try to recycle as much as I can, so you see, those vials are precious to me. If you'd be willing to go out and retrieve them, I could show you what I've been making to help combat the demons.", progress = "How goes the search? Any luck on finding my vials?", completion = "You've found some! These will certainly be enough to get us by for a good while longer.\n\nAs promised, here is a recipe for one of the potions I brew to help in our fight against the Legion.", objectives = "Go to the Petrified Forest and reclaim 12 Used Vials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48003] = { id = 48003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord's Behest", description = "Lord Norwington will want to thank you for saving his son himself. Why don't you come to the estate? We're preparing for a festival, and everybody's welcome.\n\nWe'll go ahead and tell him of all that has happened. See you there!", completion = "You're {name}? The hero that saved my son from the troggs?\n\nHohoho! You are very welcome at my estate! You must regale me with your tales of your gallant rescue!", objectives = "Meet Lord Aldrius Norwington at the Norwington Estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48004] = { id = 48004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginner Equitation", description = "You may know how to ride already, but you don't know how to ride like a Kul Tiran!\n\nWe'll let you borrow a horse for the festivities. Take one of our lesson masters, Cooper. He's trained many a beginner in his day!\n\nMount up, get in the ring, and show us what you've got! I'm sure you'll be a quick learner!", progress = "Kul Tiran riding is a true show of mastery and sport!", completion = "Well done, {name}! I think you're ready to take it to the next level!", objectives = "Mount Cooper and practice your Kul Tiran riding skills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48005] = { id = 48005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Our Guest", description = "My dear friend {name}, I do hope you enjoy the festival. I throw it every year to bring riders from all over Kul Tiras together for a grand celebration of the sport!\n\nIn fact, you deserve the whole nine yards. Please, tour the estate at your leisure and partake in the delicious food and drink, introduce yourself to the people. I insist!", progress = "Have you taken your tour yet? Take a break from adventuring and relax!", completion = "How are you enjoying the grounds? We are still setting up, so it will be even more marvelous soon!\n\nTo tell you the truth, I have to one-up myself every year. It's quite exhausting organizing it all, but it's so very rewarding!", objectives = "Tour the estate and partake in the festivities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48008] = { id = 48008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Cargo", description = "By the time I realized what was happening, it was too late.\n\nPeople had been acting strange, but I thought nothing of it. After all, they seemed to still be doing their jobs.\n\nWhile inspecting some of the cargo, this grub jumped out in an attempt to latch onto my face. I managed to take it out, but it was too late.\n\nAll of the shipments are infected. Take this torch. Destroy them.", progress = "If I had only noticed sooner, perhaps some of this could be avoided.", completion = "All we can do now is try to contain the threat.", objectives = "Burn 5 Infested Cargo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48009] = { id = 48009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal of the Guard", description = "My boys have gotten in too deep.\n\nThey've given in to whatever dark forces are at work here.\n\nDo not hesitate to do what you need to and put them down. They knew what they were signing up for when they picked the wrong side.", completion = "You did what needed to be done.", objectives = "Kill 10 Mind-Addled  Enforcers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48013] = { id = 48013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Trackers", description = "{name}, have I told you about my tracking potion? Our scouts use it to track demons, especially their \"fiends\".\n\nThose particular creatures tend to consume the astral glory in the area, making it difficult to replenish our stores of the herb.\n\nIf you could help thin their numbers out, it would greatly help us from having to search elsewhere for supplies. You can find many of them in the Annihilan Pits.\n\nI could also teach you the recipe for this potion for your effort.", completion = "You're an honorable ally, {name}. Thank you for helping us.\n\nAs promised, here is the recipe for the potion.", objectives = "Kill 14 Feflame Scavengers at the Annihilan Pits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48014] = { id = 48014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Riffraff", description = "The naga sent their tiny, foul, muck-smelling minions into our camp. They are quite bothersome. \n\nIf we do nothing, and their numbers continue to grow, they could pose a threat.\n\nYou look quick and handy. Could you perhaps expunge a few for us?", completion = "Maybe, some day, they will learn to think for themselves. Or at least choose a master more wisely.", objectives = "Slay 6 Gilblins at the Scavenger's Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48015] = { id = 48015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scrolls of Gral", description = "These gilblins are ridiculous! They are like a swarm of angry bees, buzzing around.\n\nHmm, maybe not bees. Bees are useful, and make honey, and don't steal things.\n\nThey ransacked our scrolls. Most were unusable, but there were three that are quite... potent. \n\nIt would be most unfortunate if those made it back to their masters, the naga. Please clean up their mess and bring back our scrolls.", progress = "Ah, {race}. I was always fascinated by your native language.", completion = "These scrolls must be kept safe.\n\nI dare not think how the naga could have used the secrets within, should they have deciphered them.", objectives = "Collect the 3 Tortollan Scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48016] = { id = 48016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascending Alchemy", description = "I've seen other alchemists come through our camp carrying interesting looking trinkets. I believe they refer to them as... \"alchemist stones\"?\n\nI can sense the power they radiate, but they appear fel-tainted. The herb that grows on this planet is particularly good at cleansing corruption. I use it to purify the primal sargerite that's often found amongst the herbs.\n\nI'm certain that if we used a purified sargerite with one of those stones, we could elevate the power within it.", progress = "I know it's a lot of materials to ask for, but it's necessary.", completion = "And there you have it! I believe this will be far more useful for you in your fight against the Legion.\n\nAllow me to explain how it's done...", objectives = "Bring Funen 75 Astral Glory, 5 Primal Sargerite and a Bound Infernal Alchemist Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48021] = { id = 48021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromie", description = "{name}. Is that you?\n\nI'm convinced that something unusual has happened in the timelines. I need your help!\n\nCome find me at Wyrmrest Temple, in Dragonblight, and I'll show you.", progress = "Any luck traversing the timeways?", completion = "Despite her troubles, this has been a welcome reminder that, although our battle with the Legion remains at the forefront of our concerns, the rest of the world does not simply wait for us.", objectives = "Reach \"Timehopper\" friendship rank with Chromie in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48022] = { id = 48022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48023] = { id = 48023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders Received", description = "We need ta be knowin' who be leadin' da naga in snatchin' all dese cute frogs. \n\nDey got chests around here dat have some kind of scroll dey be readin'. Da ladies be tellin' da men to remember dem orders.\n\nGet me some of dem scrolls so we can be seein' who be callin' da shots.", objectives = "Recover 5 Explicit Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48025] = { id = 48025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving for Later", description = "We need time to recover the artifacts from this place. Time the naga will not let us have.\n\nHowever, we do have a plan.\n\nWe simply hide what we don't want them to find, and then come back in a decade or two. They will have forgotten about this place by then.\n\nTake this illusion scroll and use it to conceal the notable artifacts of power.", progress = "How is that scroll working out?", completion = "Naga may be long lived, but their attention spans are not what they once were.\n\nThese antiquities should remain safe and preserved until we return.", objectives = "Conceal the antiquities of Gral.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48026] = { id = 48026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath the Waves", description = "Those witches dare! In my temple? \n\nSiavass is stretching past the realm of that which she can comprehend. There is a darkness seeking them, and they call to it! Her kind will become no more than a hollow tool to those who may answer.\n\nI feel it moving beneath us, around us. I feel it like a tremor through my being. \n\nThere is a pressure there, it has a weight greater than that of the deepest ocean. \n\nWe must stop them. They are not welcome here!", completion = "The naga are trying to hide something. My strength may be waning, but one should never underestimate a loa.", objectives = "Slay Summoner Siavass and the Whispering Horror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48027] = { id = 48027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glory of Argus", description = "<Amazed that anything so pure could continue to grow on this planet, you pick the flower from the ground. You feel a small power radiate from it and then vanish.>\n\n<As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.>", completion = "So you were trying to gather astral glory I see. Yes, there is a method to doing it correctly.\n\nThe flower has a power to it, allowing it to protect itself from anything it thinks may seek to destroy it. If it feels truly threatened, it extinguishes itself.\n\nYou mustn't try to pick it with intent to harm, but to protect. It's an unfortunate irony as we eventually destroy it in the process of making items with it.\n\nHowever, this deception is necessary for it to yield itself to you.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48028] = { id = 48028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Youthful Resistance", description = "<As you begin to gather the flowers, you realize that some of the younger blooms are still resistant to your approach and refuse to yield. Perhaps Funen might know more about how to handle the herb in its adolescent stages.>", completion = "Indeed, the newer blooms are particularly stubborn and would rather give up their life than live in servitude to those who pick them.\n\nTo handle the herb in this form, one must coax the herb into submitting, as it can't quite fully read the intentions of those who wish to gather it.", objectives = "Ask Funen about how to handle the younger Astral Glories.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48029] = { id = 48029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of It", description = "<Having handled astral glory for a while now, you've picked up on something interesting about its roots. Tightly wound in a cocoon, small flecks of light permeate through the cracks creating a shimmering effect.>\n\n<Perhaps Funen might be able to expand on the nature of these lights.>", completion = "I see the glory has come to trust you fully. It is now exposing its heart to you.\n\nFocus your intentions here and you will gather it in its entirety.", objectives = "Ask Funen about the shimmering roots of the Astral Glory.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48030] = { id = 48030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Stratholme Scene Seen" }
quests[48031] = { id = 48031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Andorhal Scene Seen" }
quests[48032] = { id = 48032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Hyjal Scene Seen" }
quests[48033] = { id = 48033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Well of Eternity Scene Seen" }
quests[48034] = { id = 48034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empyrium Deposit Chunk", description = "<As you swing your pickaxe into the ore, it hits with a resounding thud, sending a small chunk of it to the ground. At this rate, it would take you all day to get a sufficient amount of ore from this deposit.>\n\n<Perhaps someone can give you some insight into how to mine this deposit properly.>", completion = "Empyrium requires a precise strike to yield the best results. Aim your pick at the brightest bits of the ore, which also happen to be very small, hence the precision.\n\nThis will break the deposit apart faster and you'll be able to harvest ore quicker.", objectives = "Find someone on the Vindicaar who might be able to train you on how to mine an empyrium deposit.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48035] = { id = 48035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angling For a Better Strike", description = "<Looking at the empyrium dust from taking down this deposit, you wonder if there's a way to prevent part of the deposit from shattering with each impact.>\n\n<Perhaps Khamir will know something further that he can share with you.>", completion = "As I mentioned before, precision is key with mining empyrium. You've learned to strike at the correct spots, now you must learn to strike at the correct angle.\n\nTake out your pick and I'll show you what I mean...", objectives = "Speak with Khamir and see if there's a better way to mine empyrium deposits.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48036] = { id = 48036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precision Perfected", description = "<While you've learned to extract as much of the deposit as you can, the core of the deposit is always left unusable. Looking closely, you can see where your strikes were causing fractures in its structure.>\n\n<One more lesson from Khamir might be needed to correct this problem.>", completion = "You've learned where to strike and at what angle to strike, but should you wish to leave the core intact to mine, you must finally learn how hard to strike.\n\nThe fractures you found in this core are the result of striking the ore too hard. As I'm sure you no doubt know by now, mining empyrium is not just a task, but an art.\n\nCome, let us practice your swing until it's just right.", objectives = "Speak with Khamir and see if there's an even better way to mine empyrium deposits.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48037] = { id = 48037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empyrium Seam Chunk", description = "<At first you thought the ore to have a mirrored surface, reflecting the starry space above you. After breaking off a chunk, you realize that the ore itself has a starry quality all of its own.>\n\n<Perhaps someone back at the Vindicaar can give you some insight on how to better extract these seams more efficiently.>", completion = "Empyrium is quite a sight to behold once it's been mined. And while the deposits of this ore require precision, the seams require exposure.\n\nIf you spend some time picking away the surrounding rock, you'll find much more ore to harvest.", objectives = "Find someone at the Vindicaar who might be able to train you on how to mine empyrium seams.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48038] = { id = 48038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Just Pick At It", description = "<Even though you've learned to expose the ore, large chunks of it still seem to be embedded in the surrounding rock. Picking those pieces away may not result in the pure form of empyrium that you're looking for.>\n\n<Perhaps Khamir can show you a way to remove the ore from these sections of the seam.>", completion = "Empyrium seams can be tricky in that regard. The ore is very good at interweaving itself into the surrounding elements.\n\nI've found that striking those areas with the shaft of the pick loosens the empyrium's grip on it, so that when you pick at it, the rock should just fall away.", objectives = "Speak with Khamir about a way to extract more ore from empyrium seams.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48039] = { id = 48039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balancing the Break", description = "<Getting down to the root of the seam, you're left with nothing but small bits and pieces. Collectively though, they would have been enough to work with.>\n\n<Khamir might know a way to prevent this from happening.>", completion = "Much like the deposit, empyrium requires a balanced extraction. Its core is its most fragile section.\n\nIf you swing too hard, it breaks, too soft and you'll be there forever. The same is true for loosening it from its surrounding rock.\n\nHere, let me show you a method which balances both.", objectives = "Speak with Khamir about a way to extract even more ore from empyrium seams.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48040] = { id = 48040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Scraps", description = "<As you begin to carefully remove the skin from the corpse, you notice it quickly becoming corrupted by the decay of the creature.>\n\n<Pulling away, you were only able to extract a small amount of leather and something foul smelling. Perhaps someone on the Vindicaar might know more about this foul hide.>", completion = "If you haven't already guessed, the key to skinning these creatures properly is speed. They're born of foul energies and those spill out once you begin to cut into the corpse.\n\nI would suggest training your hand to become faster at removing the hide.", objectives = "Find someone at the Vindicaar who might be able to train you on how to skin fiendish leather.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48041] = { id = 48041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Larger Cut", description = "<While you've become quicker at removing pieces of the hide, there is still much that is spoiled before you're able to remove it.>\n\n<Enstraa might have a better idea of how to remove more of the hide before it becomes tainted.>", completion = "So you've become faster, but you're still thinking in your old ways.\n\nInstead of cutting away small pieces at a time, try making one large cut and removing as much of the hide in as few cuts as possible. Move away from the corpse and begin cutting the large pieces into smaller, usable pieces.", objectives = "Speak with Enstraa about a better way to remove fiendish leather.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48042] = { id = 48042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Order of Operations", description = "<The skins have been more abundant, but you're only able to gather a couple teeth and claws before they take on the corruption.>\n\n<Unsure as to how to extract as many teeth and claws as possible, you find yourself wanting to have one last conversation with Enstraa back at the Vindicaar.>", completion = "So it's just more teeth and claws you're after? This should be simple to explain then.\n\nThe teeth receive the greatest exposure to the creature's foul insides, so removing them first will still give you time to dissect the rest of the beast. Next, remove the hide. And lastly the claws, as those take the longest to take on any corruption.", objectives = "Speak with Enstraa about a better way to dissect the beasts of Argus.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48043] = { id = 48043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Plating Cleared" }
quests[48044] = { id = 48044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Shields Cleared" }
quests[48053] = { id = 48053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weigh Anchor", description = "{name}, I was hoping to ask you for a small favor. The naval fleet at Stormwind Harbor have been requesting large amounts of felslate to help construct supplies for their ships.\n\nI'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them?\n\nI heard there's a portal to Stormwind in the Greyfang Enclave here in Dalaran so it shouldn't be a long trip or anything.", progress = "Did Alard send you?", completion = "Whaddya got for me?\n\nMore felslate, fantastic! This stuff weighs a ton, and is perfect for anchors.\n\nI see you have the arms of a blacksmith. Perhaps you'd like ta have a hand at making a few anchors as well, eh?", objectives = "Bring the Crate of Felslate to Walcott Sutton at Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48054] = { id = 48054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weigh Anchor", description = "{name}, I was hoping to ask you for a small favor. The naval fleet at Bilgewater Harbor have been requesting large amounts of felslate to help construct supplies for their ships.\n\nI'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them?\n\nI heard there's a portal to Orgrimmar in the Windrunner's Sanctuary here in Dalaran so it shouldn't be a long trip or anything.", progress = "Did Vridiel send you?", completion = "More felslate, fantastic! This stuff weighs a ton, and is perfect for anchors.\n\nI see you have the arms of a blacksmith. Perhaps you'd like to have a hand at making a few anchors as well, eh?", objectives = "Bring the Crate of Felslate to Kruda Thunderhand at Bilgewater Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48055] = { id = 48055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empyrial Strength", description = "I see my armor's caught your interest. It's made from the finest material on Argus: empyrium. I actually specialize in crafting breastplates.\n\nI could show you how to craft one, but you'll need to bring your own supplies, I'm afraid. Our stores of the ore are low and we need all that we have.\n\nBut here are the plans so you'll know what you need to find...", progress = "I hope those plans weren't too complicated for you to understand.", completion = "This is quality work. It appears you even solved an issue I was having with the spacing between the front and back chest plates.\n\nYou wouldn't mind if I kept this, would you? A fair trade for the recipe, yes?", objectives = "Craft an Empyrial Breastplate. You can find the materials from gathering the ore from Argus, from other players, or from the auction house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48056] = { id = 48056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Harsh Mistress", description = "So there I was thinkin' about how to get everyone ready for movin' around Argul or whatever it's called, since I figure its gravity is different than ours, and I come up with a design for a device you slip onto your shoes, or hooves or whatever you're wearin' down there.\n\nNext thing I hear, the gravity on that planet? Completely the same as ours!\n\nRegardless, I figure I could get the prototype workin'. Mind givin' me a hand? Maybe when we're done you can like, sell 'em to kids or somethin'.", progress = "This is gonna be fun... to watch!", completion = "That last jump looked about what I had in mind for how the gravity was gonna be.\n\n<Hobart scribbles some notes on the schematic.>\n\nAnd there ya have it. They'll only last ya a few minutes before they're spent, so use 'em wisely.", objectives = "Help Hobart calibrate the Prototype Gravitational Reduction Slippers around Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48058] = { id = 48058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana-Etched Regalia" }
quests[48059] = { id = 48059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der'izu Armor" }
quests[48060] = { id = 48060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Battleplate" }
quests[48061] = { id = 48061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidian Prowler's Garb" }
quests[48062] = { id = 48062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Crusader" }
quests[48064] = { id = 48064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goroth Intro" }
quests[48065] = { id = 48065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extraterrestrial Exploration", description = "{name}, I hear you've been over to that large green planet in the sky already. Swarming with demons too, I hear.\n\nI was thinking maybe we could put together another wormhole generator for it. Make it easier to zip around the planet.\n\nProblem is we need to get readings on the landscape, and I'd go, but uh... well I need to stay here and run the shop. Can't leave it to these bozos to handle.\n\nHere, take this and get some readings for me, will ya?", completion = "Oh, this is great stuff. That's some landscape up there! Let me just get this information written down...\n\n<Didi begins to scribble some notes on some blueprint paper.>\n\nThat should do it. As with all generators, you'll need to use local materials for it, so whatever you can find on that planet should work.", objectives = "Use the Ionized Geographical Recorder at the locations marked on your map. Return to Didi when you're finished.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48066] = { id = 48066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast for Our Kin", description = "Ah, the Highmountain tauren. They have been our allies ever since we felled the Legion.\n\nAre you interested in hearing how they joined the Horde? It is quite the tale!\n\nIt all began with Baine Bloodhoof and Mayla Highmountain. Baine was hosting a great feast in Thunder Bluff to welcome the Highmountain tauren...", completion = "Welcome, {name}.\n\nMayla speaks of you as a trusted ally. Your presence will surely help convince her of the merits of joining the Horde.", objectives = "Meet Baine Bloodhoof at Thunder Bluff in Mulgore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48067] = { id = 48067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Over Thunder Bluff", description = "A dark force has descended upon us. I refuse to believe that the Highmountain are behind it.\n\nThe cacophony out there is disturbingly familiar. Could it be... \n\nNo! The minions of the Old Gods are attacking! We must fight for Thunder Bluff, {name}!", progress = "For the Old Gods to manifest even these fledgling minions is troubling.", completion = "The Old Gods are known for subversion and duplicity. To attack so brazenly...\n\nWhatever they seek, they want it badly.", objectives = "Slay 4 Dark Tendrils and 12 Shadows of Uul in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48069] = { id = 48069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrench Calls", description = "{name}, Didi the Wrench is looking for you back in Dalaran. You might want to see what she's working on. Pretty fancy stuff from what I heard.", completion = "{name}, you came at the perfect time. I just finished creating this Ionized Geographical Recorder.\n\nNow, here's how you're gonna use it...", objectives = "Meet with Didi the Wrench in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48070] = { id = 48070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Norwington Festival", description = "To whomever receives this invitation,\n\nYou are cordially invited to the 15th annual Norwington Equestrian and Hunt Festival!\n\nPeople of all walks of life from across Kul Tiras shall gather to delight in life's greatest competitions, equestrianism and hunting, while meeting those of like minds and fine tastes.\n\nHunting events shall start first, led by Abbey Watkins in Foxhollow Woods. They shall be followed by equestrian events at the Norwington Estate.\n\nWe hope to see you there posthaste!", completion = "Welcome, traveler! Care to join in the hunt?", objectives = "Meet Abbey Watkins at the edge of Foxhollow Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48074] = { id = 48074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Over Me", description = "When I rallied to the Xenedar, I left behind a valuable tool. My lightweave loom. Without it, I'm forced to labor for much longer to make garments of power for our allies.\n\nBut you are powerful, much more so than I. Perhaps you could do me a favor. Should you happen to be in the Arinor Gardens, could you retrieve my loom and return it to me?\n\nI'd be more than willing to share my knowledge of sewing lightweave with you.", progress = "Any luck in finding my loom?", completion = "You have no idea the time you've just saved me, {name}. You have my utmost gratitude.\n\nAnd as promised, here is my most coveted design.", objectives = "Go to the Arinor Gardens and retrieve Khaela's Lightweave Loom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48075] = { id = 48075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Colorful Key", description = "{name}, I hear you're a jewelcrafter. I too am a master cutter, but I fear my designs will be lost to the Legion.\n\nI hurried out of my home with the intention of returning, but I fear that may not be a possibility. You see, I left my most prized possession, a book of jewelcrafting designs.\n\nBut you, you're strong, you could fight your way into my home and recover my book!\n\nHowever, I locked it away in a special chest that requires the gems of this land to unlock. You'll need one of each to open it.", progress = "The combination isn't that difficult, just put the gems in their appropriate settings.", completion = "My book! And it doesn't appear to be damaged either, thank the Light.\n\nLook here, {name}.\n\n\n\nHere are the designs for turning those gems into accessories of power.", objectives = "Travel to Vorel's home and unlock his chest using each of the six gems that come from prospecting empyrium. Recover his jewelcrafting book and return to him on the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48076] = { id = 48076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crowning Achievement", description = "With my book nearly being lost forever, it occurs to me that I shouldn't keep all this knowledge in one place. I would like to pass it along to you, {name}.\n\nMy most recent designs are ones that I am particularly proud of. I call them Empyrial Crowns. Each one uses a different combination of gems to render different effects of power.\n\nLet me show you how to construct one and then I'll show you how different combinations of gems create different results.", progress = "Perhaps in time you too will find a student whom you may pass all your knowledge unto.", completion = "Excellent work, {name}. Now, onto the different combinations...", objectives = "Craft an Empyrial Crown for Vorel. You can find the materials from gathering and prospecting the ore from Argus, from other players, or from the auction house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48077] = { id = 48077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stoat Hunt", description = "One of the greatest hunting sports amongst the nobles of Boralus is the stoat hunt. It is a sport of determination, patience, and skill. Do you think you can rise to the challenge?\n\nStoats are agile, sneaky, and sharp. They're next to impossible to catch out in the forest, so the best way to find one is to find its burrow and scare it out.\n\nFind their burrows and bring back their pelts. Their fur is soft and much loved amongst the nobles.", progress = "Have you collected enough stoat pelts?", completion = "Not only will these pelts please the nobles, they also prove your worth as a hunter.", objectives = "Collect 5 Soft Stoat Pelts from Faintstep Stoats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48078] = { id = 48078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counterbalancing", description = "In the past, I was able to make glorious items from the beasts of this land. But then the Legion came and wiped out all those amazing beasts.\n\nNow I'm forced to use their polluted hides to craft armor for my allies. I have, however, found a way to remove their taint.\n\nThe cloth we use is made from special thread infused with Light energy. I devised an oil which when combined with the cloth purifies the leather and makes it usable.\n\nHere, take my oil and see for yourself.", progress = "I often dream of working with unsullied leather again. But who knows when that will ever be...", completion = "An interesting balance, but necessary. You may keep the oil, I have plenty.\n\nOh, and now that you know how to purify the leather, let me show you how to use it. Here are some shoulder patterns my allies ask for regularly.", objectives = "Gather Fiendish Leather and Lightweave Cloth and use Enstraa's Tanning Oil to create 12 Purified Fiendish Leather.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48079] = { id = 48079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Highmountain", description = "Spiritwalker Ebonhorn remains in great danger. He and Mayla have returned to Highmountain, but I believe they still need our aid.\n\nLet us journey to Thunder Totem and do whatever we can to mend Ebonhorn. Perhaps our deeds will strengthen the bond between our peoples.", completion = "Ebonhorn has spoken of ancient wards that must be maintained in Highmountain. Wards that hold back a great darkness.\n\nThis may be tied to the evil that grips him now.\n\nWe must hope that Spiritwalker Graysky can tell us more.", objectives = "Meet Mayla Highmountain at Thunder Totem in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48080] = { id = 48080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Element of Danger", description = "These nobles really think killing weasels is the mark of a good hunter? Ha!\n\nIt ain't hunting if there isn't a bit of danger involved. There are boars in these woods. That's more our speed out in the mountains! Why don't you kill some of those, then bring me their tusks as proof?", progress = "Boars actually present some semblance of challenge to the hunter.", completion = "<Harold lets out a hardy laugh.>\n\nNow that's what I'm talking about!", objectives = "Collect 8 Rugged Boar Tusks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48081] = { id = 48081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Floating Ruin", description = "We knew the Legion to be a formidable foe, but recent events demonstrate that we do not possess the necessary strength to continue. We have come too far to fail at this critical moment.\n\nI know of a relic on Eredath, my ancient home, that may be our salvation. We must take the Vindicaar beyond the surface of Argus, to the floating ruin suspended above us.\n\nPerhaps there we will find the salvation we so desperately need.", completion = "<Velen's gaze is drawn to the ruins spread out before him.>\n\nI am home.", objectives = "Travel to Eredath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48082] = { id = 48082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48083] = { id = 48083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48084] = { id = 48084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48085] = { id = 48085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48087] = { id = 48087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equine Retrieval", description = "I like the cut of your jib, friend!\n\nI'll tell you what. The rest of the partygoers should be arriving any time now. Would you do me the honor of retrieving my favorite horse from the estate on the hill?\n\nImagine, our guests' first impression of you to be on the most regal horse in all of Tiragarde! Wondrous!", progress = "{name}! The troggs have invaded!", completion = "I don't believe I'm saying this, {name}, but troggs are invading the estate!", objectives = "Retrieve Lord Norwington's favorite horse Rose from his hilltop estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48088] = { id = 48088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Party Like a Trogg Party", description = "Troggs? At my party?\n\nMy grandfather pushed them back to that cleft years ago to build this estate. To think that they would attack in such force after all these years?\n\nThis is just what we needed to make this year's festival the greatest ever!\n\nShow us your heroism firsthand, {name}! Mount Cooper and defeat these troggs! Drag them behind you, jab them with your harpoon... whatever it takes!", completion = "A grand showing! You had me on the edge of my seat!", objectives = "Kill 20 Grimestone troggs in Norwington Estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48089] = { id = 48089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mountain Sounds", description = "Kul Tirans won't go down without a fight!\n\nTake this horn. We use it in the mountains to warn each other of danger and lead the charge into battle. Use it to rally our allies against the troggs!", progress = "We are stronger together!", completion = "Our people defend the estate with renewed vigor!", objectives = "Use the Horn of the Mountain to rally 8 Kul Tirans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48090] = { id = 48090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krag'wa's Chosen", description = "Dis be a real mess, {name}. Da naga be drainin' da magic of Krag'wa's frogs ta feed demselves!\n\nDere be three frogs, Krag'wa's champions, dat dey be torturin' as we speak.\n\nTake dis potion, it be returnin' da power of dem noble frogs. Dey deserve better dan bein' drained by dese snake bastards.\n\nI be stayin' here. Da naga got in some lucky hits on me. All me life, I wanted ta see Krag'wa, and I let meself get hurt by some naga!", completion = "Ya did it! Krag'wa gonna be pleased wit' dis, I be sure of it.", objectives = "Rescue Krol'dra the Wise, Wok'grug the Clever, and Wag'shash the Bold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48091] = { id = 48091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vagath the Betrayed" }
quests[48092] = { id = 48092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance of the Frogs", description = "Da naga here be led by a priestess, Zaldraxia. She be da one dat figured out how ta drain da frogs of their magic.\n\nZaldraxia be stoppin' at nothin' ta drain every frog here.\n\nDo what I could not, and kill dis priestess. Show da naga dat Krag'wa ain't a loa ta be takin' lightly.\n\nI be prayin' ta Krag'wa for ya success.", completion = "Wit' Zaldraxia dead, da naga should be leavin' soon. Ya did what I couldn't, and for dat ya have me thanks.\n\nKrag'wa's blessin' be on ya, I be hopin' soon he recognizes me devotion ta him.", objectives = "Defeat Priestess Zaldraxia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48093] = { id = 48093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagating the Threat" }
