quests[48106] = { id = 48106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Love Lost" }
quests[48107] = { id = 48107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sigil of Awakening", description = "This relic is too powerful to keep it out in the open.\n\nWe must return to the Vindicaar at once. The Prophet will know what to do.\n\nI did want to thank you, {name}. Without you this would not be possible. Quoram would have ensured I never got near the Sigil. Perhaps some day I will share that story with you.", progress = "Did you recover the Sigil of Awakening?", completion = "We are that much closer to restoring the Crown of the Triumvirate to its former glory.", objectives = "Return to the Vindicaar and secure the Sigil of Awakening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48108] = { id = 48108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waycrest Daughter", description = "You seek House Waycrest? Oh, your timing could not be worse!\n\nI had just received a raven regarding Lord Waycrest's daughter, Lucille, shortly before this... curse came upon us.  They apprehended her in Fletcher's Hollow and are taking her to trial.\n\nThey say she is a witch, herself! \n\nIf she's found guilty, she will surely hang! You must make haste to Hangman's Point.  With what you've seen here, maybe you can convince them of her innocence.", completion = "Can't you see that we're busy here, {class}?\n\nI assume you have a reason for interrupting this trial...", objectives = "Meet with Constable Henry Framer at Hangman's Point in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48109] = { id = 48109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Woods Have Eyes", description = "The sooner I can return the lady Waycrest to Highroad Gate the better, but I will honor her wishes if we can assure her safety.\n\nThere are dark things happening in these lands that you don't fully understand. If we must dally, then there are measures that need be taken.\n\nFirst, the wildlife here can serve as eyes to dark powers. Kill them.", progress = "Has our foe been sufficiently blinded?", completion = "Not a beast in sight. Good.\n\nThe foes of this land must not find us here in the open.", objectives = "Kill 4 Watchful Ravens and 6 Darkmaw Prowlers in the Watchman's Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48110] = { id = 48110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Case of Ambush", description = "There is more to worry about in these woods than simple beasts. Our enemy employs constructs of wicker and bone that can rip a man apart.\n\nFortunately for us, these constructs are not very perceptive.\n\nTake these traps and set them up throughout the woods behind us.  If our enemies do seek to ambush us here, at least these will slow their minions down.", progress = "We must be prepared. Anywhere can harbor an ambush here.", completion = "Good, those traps should alert us in case anything tries to sneak up on us through the woods.\n\nYou have bought us a modicum of safety, {class}.", objectives = "Place 6 traps in the Watcher's Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48111] = { id = 48111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial by Superstition", description = "Witchcraft has long lived in the superstitions of the people here. It is only recently that some of these superstitions have become reality.\n\nAccording to tradition, one who is tried for witchcraft is allowed to choose the means by which they are tested from among the requests of her peers.\n\nThe villagers here no doubt have some strange beliefs of what witches can and cannot do. Speak with them, and see what we can do to prove my innocence.", progress = "What have you learned from the villagers?", completion = "Well, those are certainly some interesting beliefs. I think it's safe to rule out the fire and drowning, don't you think?\n\nLooks like that leaves us with three tests...", objectives = "Question 5 Fletcher's Hollow Villagers in Hangman's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48113] = { id = 48113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pungent Solution", description = "The first test should be simple enough. While I may not do so often, I am certainly capable of crying.\n\nThough to be honest, I've never had to cry on cue.\n\nMaybe you could help with that, though. Nearby there is an onion field that belonged to one of the local farmers. It's abandoned, and most of it is dried up by now, but you might be able to find one onion ripe enough in there to cause some tears.", progress = "Have you had any luck at the onion field?", completion = "Great, you found one! I was worried that there wouldn't be much left growing on that farm. \n\nThe people of Drustvar could learn a thing or two from that hardy onion.", objectives = "Collect a Juicy Onion from Hawthorne's Plot near Hangman's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48165] = { id = 48165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harmful If Swallowed", description = "This last test I am not looking forward to, but it is certainly better than being set on fire. \n\nThey say that a witch can't get sick. We will prove to them that I can.\n\nA venom comes from the saurolisks nearby that is used by our healers when a child swallows something they shouldn't. When ingested, it will make you immediately ill, emptying the contents of the stomach.\n\nYou'll need several of their venom glands to get enough venom for an appropriate dose. Removing them intact may prove difficult.", progress = "Is the deed done?", completion = "Good. This toxin should have the... desired effect.\n\nGah, I can't believe I'm going to go through with this.", objectives = "Collect 5 Intact Venom Glands from the Shallows Saurolisks near Hangman's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48170] = { id = 48170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once Bitten, Twice Shy", description = "I am all too familiar with the bloodfly's bite. We had them all over the fields surrounding Waycrest Manor.\n\nThough I'm loath to subject myself to them on purpose, if it will help convince these people, I am willing to deal with that nuisance. \n\nFind a jar and collect as many bloodflies as you can. They are common in these parts, and shouldn't be hard to find.", completion = "Well done. \n\nWith this many bloodflies at least one is bound to bite.", objectives = "Find an Empty Jar and use it to catch 6 Hovering Bloodflies near Hangman's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48171] = { id = 48171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of Fletcher's Hollow", description = "It's obvious the constable won't be swayed until we discover what happened at Fletcher's Hollow. I know very little myself--only that the village has been overrun by monstrous creatures.\n\nI must ask that you travel there in my stead and try to uncover what befell the village. I'm sure Marshal Reade will prevent the constable from harming me while you're away.\n\nDo this for me, and I will help you as I can.", completion = "You're looking to help solve this curse? Well, that's good to hear. We can surely use all the help we can get.\n\nI'm happy to help you get to the bottom of this. First things first, though, we need to save some of our villagers.\n\nCare to lend a hand?", objectives = "Speak with Evelyn Pare at the Timbered Strand in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48175] = { id = 48175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden in the Hollows" }
quests[48176] = { id = 48176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Trouble in Little Tortolla", sourceObjective = "Speak with Toki in Little Tortolla.", sourceObjectiveStatus = "unverified-source-field" }
quests[48179] = { id = 48179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue Rangers", description = "We're barely holding off those monsters here. If it hadn't been for the Thornspeakers, we'd surely be dead. I was worried Rebecca hadn't made it!\n\nYou've brought Rebecca's supplies just in time. We have many injured out in the field, Thornspeaker, ranger, and companion alike. I'll hold the line here. Go into the ruins and heal as many of the wounded as you can!", completion = "Thank you for helping us, Mainlander.", objectives = "Save 10 injured Thornspeakers, rangers, and pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48180] = { id = 48180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Really Big Problem", description = "Hey! Mainlander!\n\nI know I'm supposed to be trying to knock over cairns and hauling out lost rangers, but d'you see that massive stone monster? I'm thinking that's gonna be a problem.\n\nYou look like you know how to handle yourself. Think between the two of us we can take it down?", completion = "I suppose I'm not really surprised Arthur didn't exactly follow orders. But I don't think I can complain with the results.\n\nThanks for making sure he wasn't entirely in over his head.", objectives = "Defeat the Ancient Sentinel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48181] = { id = 48181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nooooope" }
quests[48182] = { id = 48182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total Cairnage", description = "My mentor sensed the activation of ancient powers here. We came to stop them but were too late. We banded together with the rangers for mutual protection, but our task remains unfinished.\n\nThere is a set of ancient cairns here. These help empower the Drust constructs. Destroying them will also help to settle the undead stirring from the land.\n\nDestroy the cairns and we'll be able to bring sanity to this place.", progress = "Power within those cairns does not bode well for anyone in Drustvar.", completion = "Thank you for destroying those cairns. We should be able to dismantle the Drust constructs and risen dead more easily now.", objectives = "Destroy the Ancient Cairns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48183] = { id = 48183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hills Are Alive", description = "The Drust constructs are drawn from the land, but the heart of these constructs is a runic power core. \n\nWe have been trying to collect and destroy as many of these cores as we can. We know of a way to disrupt the magic in the core. Doing so will prevent more of these monstrosities from being created around the dark hearts and protect the land and all living in this region.\n\nBring me as many Runic Power Cores as you can find and the Thornspeakers will see they are put to good use.", progress = "We would appreciate any runic power cores from the Awoken Guardians you might find.", completion = "Excellent, {name}. We can use these to protect the land and the people and creatures living here.", objectives = "Collect 6 Runic Power Cores from Awoken Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48184] = { id = 48184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of History", description = "There is an opportunity here.\n\nLearning more about the Drust can not only help us understand the texts that Lady Lucille found, we might be able to discover greater details about how they and their constructs were finally defeated. Filling in the gaps of history could be key to victory now.\n\nThis was one of their settlements before it became the place of their final defeat. Let's look for clues in the ruins.", completion = "Gorak Tul's death shattered his army! The carvings here all show that, but now I wonder... Did Gorak Tul actually die?", objectives = "Search the ruins for information about the Drust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48185] = { id = 48185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow of the Sepulcher", description = "Ebonhorn spoke of another ward safeguarding the lands of the Skyhorn tribe. Somewhere close to the Sepulcher of the Sky, he said. It was there that this \"Darkness\" once manifested.\n\nMeet me there, {name}. I will show you how to walk in the memories of a great Skyhorn hero.", completion = "The next ward is nearby. I can sense it.", objectives = "Meet Spiritwalker Graysky in Sepulcher of the Sky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48190] = { id = 48190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huln's Mountain", description = "We have made progress reactivating the wards, but more must be done.\n\nI sense Ebonhorn's struggle. Though he fights with all his strength, he is slipping away. Should this \"Darkness\" emerge into our realm, I fear our friend will be lost.\n\nEbonhorn spoke of another ward somewhere within Snowblind Mesa. Meet me there, so that I might guide you along another journey into the memories of the past.", completion = "Do you sense it, {name}? Such strength... such courage.\n\nThe echo of Huln Highmountain's spirit is all around us.", objectives = "Meet Spiritwalker Graysky at Snowblind Mesa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48192] = { id = 48192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tar Spitter" }
quests[48195] = { id = 48195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troublesome Troglodytes", description = "Troggs are base creatures. They barely have any brain process, living mostly on survival instinct alone. They are pests through and through, and need to be dealt with.\n\nThe fewer of them there are, the better.", completion = "Fewer troggs means fewer of our people getting attacked.", objectives = "Kill 8 Grimestone Bullies and 3 Grimestone Throwers in Mistfall Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48196] = { id = 48196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following Eddie's Trail", description = "My life is equestrian. I'm not a fighter. I could maybe take a trogg or two, but not a whole tribe.\n\nPlease, go into Mistfall Cleft and see if you can find Eddie. Lord Norwington would be furious if something happened to him, and nobody wants to bear witness to that!", progress = "Are... are you here to save me?", completion = "You saved me! Those troggs are really scary. They took Hotshot and dragged me through their camp!", objectives = "Follow the trail of Eddie Norwington.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48198] = { id = 48198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burden of Proof", description = "I think we have everything we need to conduct three of the villagers' tests. Let us hope this is enough to convince them.\n\nI'm sure Constable Framer is champing at the bit to proceed with his trial, and I would prefer it if you were the one to administer the tests. I may not know you well, but I trust you farther than the constable.\n\nSpeak with him when you're ready to begin.\n\n...and do me a favor. Make this quick.", completion = "That... didn't turn out as expected.\n\nIt appears that my absolution may truly be in your hands.", objectives = "Administer the tests to prove Lucy Waycrest's innocence in Hangman's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48199] = { id = 48199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Heart", description = "The loss of Xe'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us.\n\nI wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru.\n\nThis must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack.\n\nWe need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!", completion = "I never imagined such destruction... such horror.", objectives = "Use the Navigation Console to travel to the Antoran Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48200] = { id = 48200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing a Foothold", description = "Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements.\n\nOur first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts.\n\nSpeak to Romuul when you are ready to head down to the surface.", progress = "We need that teleportation beacon set up if we are to reinforce our positions.", completion = "Good. From here we can quickly access and reinforce each of the encampments.", objectives = "Travel to the Antoran Wastes and place the Lightforged Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48201] = { id = 48201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforce Light's Purchase", description = "Now that we have established a foothold, we need to rendezvous with our soldiers in the field.\n\nWe have an Army of the Light encampment to the south, near where the Legion is keeping their strongest warriors in some sort of stasis.\n\nAlleria went to scout the area. Find her, and see what information she has gathered.", progress = "The camp lies to the south. When you find the large stasis capsules, look for a passage on the left.", completion = "We have a foothold here... for now.\n\nI am unsure how long it could hold out against a sustained assault.", objectives = "Speak with Alleria at Light's Purchase.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48202] = { id = 48202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforce the Veiled Den", description = "The foothold you established allows us to check in with our field operatives.\n\nOn our last mission here, we set up a bastion to the northeast. It should be defensible for now, but that could change at any moment.\n\nIllidan has gone ahead to assess the situation. I suggest you go there and see if he needs a hand.", progress = "The camp lies to the northeast.\n\nIt may appear hidden at first glance, but you can find the Light shining in the darkest places.", completion = "So many demons. So much work to do.", objectives = "Speak with Illidan at the Veiled Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48203] = { id = 48203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Throne", description = "The time has come, {name}, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment.\n\nWe will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion.\n\nAfter all you have done, it is fitting that you have the honor. Activate the Crown of the Triumvirate and let us finish our mission.", completion = "After so many years... so many sacrifices... victory is finally within our grasp.", objectives = "Use the Crown of the Triumvirate while above the Antoran Wastes to open the way to Antorus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48230] = { id = 48230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragment of the Past", description = "<Your eye is drawn to the faint glow of the crystalline fragment. Examining the piece, you trace the partial pattern of a rune that had been inscribed upon its surface.\n\nThe fragment appears similar to the argunite crystals used by the Army of the Light to power their armaments. Could this crystal have belonged to the eredar who fought to escape Argus so long ago?\n\nPerhaps Captain Fareeya would be able to tell you more about the crystal.>", completion = "<Fareeya examines the crystal fragment.>\n\nThis is old... very old. It is a piece of an elaborate key, the sort my people use to secure our most prized and sacred places.\n\nI wonder...", objectives = "Take the Glowing Key Fragment to Captain Fareeya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48231] = { id = 48231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seat of the Triumvirate: Armor of the Triumvirate", description = "This reforged key will grant entry into the armory inside the Seat of the Triumvirate.\n\nLocked away inside is the Armor of the Triumvirate, crafted in the days before Sargeras brought ruin to our world. We cannot let this armor be stolen by the Void's forces.\n\nOnce the armor is in your possession, please bring it to Archivist Ionaa. He has collected our most sacred relics in the cave just up the path. No doubt he would be very glad to receive it.", progress = "Have you brought me something, {class}?", completion = "The Armor of the Triumvirate! I never believed I would see it again. It is a reminder of our proud history, one which the evil of the Legion will never overshadow.\n\nGaal told me of your dedication, {name}. It is fitting that you don this armor. May it serve as a beacon of the Light in these dark times.", objectives = "Secure the Armor of the Light and bring it to Archivist Ionaa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48237] = { id = 48237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeat Nekthara" }
quests[48261] = { id = 48261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power to Reforge", description = "I forged the key using a pristine argunite crystal. Unfortunately, the only ones remaining are used by the Army of the Light's defenses.\n\nHmm... dendrite clusters might be an alternative. They were used by the elite of Eredath to power simple devices. If enough of the city ruins are still intact, I'd wager the fallen magi or the broken may still have some in their possession. \n\nOf course, I would need a great many clusters to reforge the key. It seems you have your work cut out for you.", progress = "Were you able to find enough clusters?", completion = "Ah, yes. Combined, these clusters should provide just enough power for me to fuse the key fragments back together.", objectives = "Obtain a stockpile of Dendrite Clusters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48271] = { id = 48271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering the Pieces", description = "The fragment you found is only one part of the key. I fear the other pieces have fallen into the hands of these ethereal beings you speak of... the Shadowguard. \n\nWe must recover them all. The Shadowguard leaders and lieutenants in and around the Seat of the Triumvirate may well have the fragments in their possession.\n\nGet those key fragments, {name}... any way you have to.", progress = "Did you find all the fragments?", completion = "Nice work, Huntmaster. Those ethereals stood no chance against you.\n\nNow that we have the fragments, I can prepare them for reforging.", objectives = "Secure the missing key fragments from the ethereals around the Seat of the Triumvirate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48272] = { id = 48272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of Fear", description = "I've done it, <lad/lass>. I've reached him again! \n\nOh, but it's so painful. So painful! He's not doin' well, not one bit!\n\nYou'll have to listen on in with me to understand.", progress = "It's a lot to take in, I know, but it might help us while we can still be helped.", completion = "The Pantheon has been dead for thousands of years... I fear this plan has been in the works for a very, very long time.", objectives = "Witness Argus' vision with Magni.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48273] = { id = 48273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker Listens", description = "Magni has sent for you in Krokul Hovel once more. He seems to have made a new breakthrough in trying to reach Argus.\n\nI suggest you find him immediately. His last vision foretold Aggramar's coming, and there is still so much we do not know of Sargeras' plans.", completion = "Thank ye fer joinin' me, lad. There's somethin' ye have to see.", objectives = "Meet Magni in the Krokul Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48277] = { id = 48277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker Seeks", description = "Our forces are ready for battle, but we still do not know where Eonar's spirit lies.\n\nYou should seek Magni out at once and see if you can find her while we still have a chance. If she falls, nothing we muster will be able stand against Sargeras.", completion = "Ye came just in the nick of time.", objectives = "Meet Magni in the Krokul Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48278] = { id = 48278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Life-Binder", description = "I don't even want to think about what happens if Aggramar can find Eonar's spirit before we do. The fate of far more'n Azeroth may hinge on her safety.\n\nLet Turalyon know what we saw right away. We're going to need to bring all we can to bear to save her.", sourceObjective = "Return to Turalyon on the Vindicaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[48280] = { id = 48280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of Another", description = "Whoever's tryin' to reach us now might give us the information we need to find Eonar.\n\nWe need to see what's goin' on right away!", progress = "Eonar's still out there somewhere, but I don't know how much longer she'll last.", completion = "Our answer lies in the Legion's own portal network in the heart of Antorus.", objectives = "Witness Argus' vision with Magni.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
